insert into public.ai_knowledge (kind, area, country_code, topic, title, summary, source_name, source_url, license, lang, status) values
('management','impuestos','PE','calendario_obligaciones_mensuales_sunat',$k$Perú: cómo funciona el cronograma mensual de SUNAT$k$,$k$SUNAT publica cada año el cronograma de obligaciones mensuales (Resolución de Superintendencia 281-2022/SUNAT para el ejercicio 2026). La fecha de vencimiento depende del último dígito del RUC (grupos 0, 1, 2 y 3, 4 y 5, 6 y 7, 8 y 9) y existe una columna aparte para buenos contribuyentes. Se declara y paga en el mes siguiente al período: por ejemplo, el período enero 2026 vence en febrero (dígito 0: 16 de febrero, según el cronograma 2026). Cubre el PDT/Formulario 621 de IGV y renta, la planilla electrónica (PLAME) y otras obligaciones mensuales. Si el domicilio fiscal está en zona de emergencia, las fechas pueden cambiar: se consulta el Cronograma Personalizado con el RUC. Atraso: intereses y multas según la infracción. IMPORTANTE: no usar fechas de memoria; el cronograma cambia cada año. Dónde confirmar: sunat.gob.pe (Cronogramas, Cronograma de obligaciones mensuales del año) y el cronograma personalizado.$k$,'SUNAT (Cronograma de obligaciones mensuales 2026)','https://www.sunat.gob.pe/orientacion/cronogramas/2026/cObligacionMensual2026.html',$k$Material informativo de SUNAT; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.$k$,'es','draft'),
('management','impuestos','CO','calendario_tributario_dian_nit',$k$Colombia: calendario tributario de la DIAN y cómo leerlo$k$,$k$La DIAN fija cada año el calendario tributario; las fechas dependen del último dígito del NIT sin contar el dígito de verificación (renta de personas naturales y exógena usan los dos últimos dígitos). Estructura 2026 según la DIAN y prensa especializada: la retención en la fuente se declara y paga cada mes entre el séptimo y el décimo sexto día hábil; el IVA es bimestral para quienes tienen ingresos brutos iguales o superiores a 92.000 UVT y cuatrimestral para los menores; la renta de personas jurídicas se paga en dos cuotas (primera en mayo, según NIT; segunda en septiembre). La UVT 2026 es $52.374. Los grandes contribuyentes tienen plazos propios; el Régimen Simple tiene anticipo bimestral y declaración consolidada. El ICA y otros tributos locales se rigen por cada municipio. No usar fechas de memoria. Dónde confirmar: dian.gov.co (Calendario tributario, vencimientos del mes) y el calendario del municipio para ICA.$k$,'DIAN (calendario tributario y vencimientos mensuales)','https://www.dian.gov.co/Contribuyentes-Plus/Paginas/Calendario-de-obligaciones.aspx',$k$Material informativo de la DIAN y fuentes de prensa especializada señaladas; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.$k$,'es','draft'),
('management','impuestos','PY','calendario_perpetuo_dnit',$k$Paraguay: calendario perpetuo de vencimientos de la DNIT$k$,$k$La DNIT (ex SET) mantiene un calendario perpetuo: las declaraciones juradas de IVA, IRP e IRE vencen un día fijo de cada mes según el último número del RUC sin el dígito verificador, entre el día 7 (terminación 0) y el día 25 (terminación 9). La tabla publicada indica 7, 9, 11, 13, 15, 17, 19, 21, 23 y 25 para terminaciones 0 a 9. Se declara por el sistema Marangatu. Anticipos y obligaciones anuales (IRE Régimen General, IRE Simple, IRE RESIMPLE con pagos de cuota fija en marzo, junio, setiembre y diciembre) tienen su propio calendario. La DNIT puede trasladar excepcionalmente fechas por resolución (en 2026 lo hizo por fallas de Marangatu y de nuevo en noviembre), por eso hay que revisar los comunicados. Un día no hábil traslada el vencimiento, según una fuente privada: confirmar. Dónde confirmar: dnit.gov.py (Vencimientos, Calendario perpetuo y comunicados).$k$,'DNIT Paraguay (Calendario perpetuo y vencimientos)','https://www.dnit.gov.py/web/portal-institucional/w/calendario-perpetuo-continua-vigente-para-el-iva-irp-y-rentas',$k$Material informativo de la DNIT; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.$k$,'es','draft'),
('management','impuestos','CL','calendario_f29_f22_sii',$k$Chile: calendario del SII (F29 mensual y Operación Renta F22)$k$,$k$El Formulario 29 (IVA, PPM y retenciones) se presenta cada mes, incluso sin movimiento. Plazo general: hasta el día 12 del mes siguiente; quienes declaran y pagan por internet y cumplen los requisitos del SII tienen hasta el día 20, y una declaración por internet sin pago puede presentarse hasta el día 28 (fuente privada Simplo y Contable.app: confirmar condiciones en el SII). La Operación Renta (F22) se hace cada año en abril y las devoluciones se pagan desde fines de abril y mayo según la fecha de presentación (2026: declaración desde el 1 de abril, según el SII). Las declaraciones juradas anuales se presentan entre marzo y junio según el tipo y sus fechas cambian cada año. Las cotizaciones previsionales se pagan mensualmente por Previred. El calendario oficial está en el SII (Calendario tributario) y en ChileAtiende (ficha de declaración de renta). No usar fechas de memoria.$k$,'SII; ChileAtiende (Declaración de Renta, Operación Renta 2026)','https://www.chileatiende.gob.cl/fichas/3178-declaracion-de-renta',$k$Material informativo del SII y ChileAtiende y fuentes privadas señaladas; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.$k$,'es','draft'),
('management','impuestos','AR','calendario_vencimientos_arca_cuit',$k$Argentina: calendario de vencimientos de ARCA$k$,$k$ARCA publica cada mes la agenda de vencimientos y las fechas dependen de la terminación del CUIT. Estructura observada en 2026 (argentina.gob.ar y prensa especializada): IVA y Libro de IVA Digital se presentan y pagan en la segunda quincena del mes siguiente, escalonado por terminación (en junio 2026 entre el 18 y el 24); el Monotributo se paga una vez por mes en una fecha única para todas las terminaciones, en torno al día 20; los autónomos pagan a comienzos de mes (días 5 a 7 según terminación); las cargas sociales de empleadores (SUSS, formulario 931) vencen escalonadas por terminación alrededor del día 9; Ganancias de sociedades con cierre en diciembre vence en mayo escalonado por terminación; el régimen de información anual de sociedades vence en julio. Las fechas exactas cambian cada mes y año: no usar fechas de memoria. Ingresos Brutos y tasas municipales tienen calendario propio de cada provincia y municipio. Dónde confirmar: argentina.gob.ar/arca (Vencimientos) y la agenda de ARCA.$k$,'ARCA / argentina.gob.ar (Vencimientos)','https://www.argentina.gob.ar/node/437875',$k$Material informativo de ARCA y fuentes de prensa señaladas; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.$k$,'es','draft'),
('management','impuestos','BR','calendario_obrigacoes_das_esocial_dctfweb',$k$Brasil: calendario mensual y anual de obligaciones (Simples, eSocial, DCTFWeb)$k$,$k$Fuentes profesionales brasileñas (Agilize, Razonet, C6 Bank, Jornal Contábil) coinciden en este patrón de fechas, que depende del régimen y puede variar por feriado o fin de semana: el DAS del Simples Nacional y del MEI vence el día 20 del mes siguiente, con multa de mora; el FGTS el día 7; el eSocial y la DCTFWeb alrededor del día 15 (la DCTFWeb mensual, según una fuente, hasta el 15.º día hábil del segundo mes siguiente: fuentes difieren, confirmar). La DEFIS del Simples se presenta hasta el 31 de marzo y la declaración anual del MEI en mayo (confirmar). Empresas en Lucro Presumido o Real tienen DARF de IRPJ y CSLL, EFD-Contribuições y EFD-ICMS/IPI con plazos propios. ICMS e ISS dependen del estado y del municipio. No se pudo leer el calendario oficial de la Receita Federal en esta consulta: la ficha se apoya en fuentes privadas. Dónde confirmar: gov.br/receitafederal (Agenda Tributária), Portal do Simples Nacional y el contador.$k$,'Fuentes profesionales brasileñas (Agilize, Razonet, Jornal Contábil); Receita Federal','https://agilize.com.br/artigos/obrigacoes-fiscais-microempresa-simples-nacional',$k$Material informativo de fuentes profesionales; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.$k$,'es','draft'),
('management','impuestos','MX','calendario_fiscal_sat_personas_morales',$k$México: calendario fiscal del SAT para personas morales$k$,$k$Fuentes especializadas (Expansión, Siigo, El Contribuyente) coinciden en el patrón general: pagos provisionales de ISR, declaración definitiva de IVA y retenciones se presentan a más tardar el día 17 del mes siguiente (RESICO personas morales también presenta ISR e IVA mensual); la DIOT y la contabilidad electrónica se envían mensualmente, con plazo hacia el último día del mes siguiente (confirmar con el SAT); la declaración anual de ISR de personas morales vence el 31 de marzo del año siguiente; la PTU a los trabajadores se paga en mayo (confirmar fecha) y el aguinaldo antes del 20 de diciembre. Cuando el día cae en inhábil se recorre al siguiente hábil. Algunos casos reciben días adicionales según el sexto dígito del RFC. IMSS e Infonavit tienen calendario propio. No usar fechas de memoria. Dónde confirmar: sat.gob.mx (Calendario de obligaciones) y la Resolución Miscelánea Fiscal vigente.$k$,'SAT; fuentes especializadas (Expansión, Siigo)','https://www.bbva.com/es/mx/empresas/calendario-fiscal-2026-para-personas-morales-en-mexico-y-fechas-esenciales-del-sat/',$k$Material informativo de fuentes especializadas y del SAT; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.$k$,'es','draft'),
('management','impuestos','EC','calendario_tributario_sri_noveno_digito',$k$Ecuador: calendario tributario del SRI por noveno dígito del RUC$k$,$k$En Ecuador la fecha máxima de la mayoría de declaraciones depende del noveno dígito del RUC o cédula. El esquema general mensual va del día 10 al 28: dígito 1 el día 10, dígito 2 el 12, y así de dos en dos hasta el dígito 9 el 26 y el dígito 0 el 28; si cae en fin de semana o feriado pasa al siguiente día hábil, salvo que eso cambie de mes, en cuyo caso se anticipa al último día hábil. Cada mes se declaran el IVA (formulario 104), las retenciones en la fuente (formulario 103), el ICE (105) y el ISD si corresponde. El IVA puede ser semestral para quienes cumplen las condiciones del SRI. La declaración y el pago se hacen de forma simultánea en el SRI en Línea. Anuales: renta de sociedades en abril (según noveno dígito), RDEP del empleador entre fines de enero y febrero, información de composición societaria en febrero, RIMPE en abril. Los contribuyentes especiales tienen fechas propias. El SRI amplía plazos por resolución en algunos años: no usar fechas de memoria. Dónde confirmar: sri.gob.ec (Calendario tributario).$k$,'SRI Ecuador y prensa especializada','https://www.siigo.com/ec/blog/obligaciones-fiscales/calendario-tributario-sri/',$k$Material informativo del SRI y fuentes privadas señaladas; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.$k$,'es','draft'),
('management','impuestos','UY','calendario_vencimientos_dgi_bps',$k$Uruguay: calendario general de vencimientos de la DGI$k$,$k$La DGI publica cada año el Calendario general de vencimientos, organizado por grupo de contribuyente (entes autónomos, grandes contribuyentes, otros) y por último dígito del RUT. Incluye pagos mensuales de IVA, anticipos de IRAE (hay planilla para el anticipo mínimo según la UI), IVA mínimo (vencimiento alrededor del día 20 de cada mes), pagos a cuenta de servicios personales (bimestral), declaraciones juradas y el Impuesto al Patrimonio de personas físicas. La DGI modifica fechas por resolución (en 2026 hubo varias prórrogas): revisar siempre el calendario actualizado y las resoluciones. Los aportes patronales a BPS tienen calendario propio y existe una bonificación de buen pagador del 10 % sobre aportes jubilatorios patronales (BPS, comunicado 1/2026: confirmar condiciones). No usar fechas de memoria. Dónde confirmar: gub.uy/direccion-general-impositiva (Vencimientos 2026, calendario general actualizado) y bps.gub.uy.$k$,'DGI Uruguay (Vencimientos 2026); BPS','https://www.gub.uy/direccion-general-impositiva/comunicacion/publicaciones/vencimientos-2026-calendario-general-actualizado',$k$Material informativo de la DGI; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.$k$,'es','draft');